        \Longleftrightarrow \;\; & \forall P_A \in \Delta(\mathcal{A}), \, \gamma(P_A) = \textstyle\sum_{a \in \mathcal{A}} P_A(a) \gamma(\mathds{1}_a) \label{eq:lemma1B}
    \end{align}
    where $\mathrm{int}(\Delta(\mathcal{A}))$ is the interior of $\Delta(\mathcal{A})$ (i.e. the full-support distributions on $\mathcal{A}$).

\begin{align}
        & \exists P_A \in \mathrm{int}(\Delta(\mathcal{A})), \, \gamma(P_A) = \textstyle\sum_{a \in \mathcal{A}} P_A(a) \gamma(\mathds{1}_a) \label{eq:lemma1A}\\
